package com.example.dizifilim import com.lagradost.cloudstream3.* import com.lagradost.cloudstream3.utils.* import com.lagradost.cloudstream3.network.* import org.jsoup.nodes.Element class DiziFilim : MainAPI() { override var name = "Dizi Filim" override var mainUrl = "https://www.hdfilmcehennemi.nl/" override var lang = "tr" override val hasMainPage = true override val hasQuickSearch = true override val supportedTypes = setOf(TvType.Movie, TvType.TvSeries) override suspend fun search(query: String): List<SearchResponse> { val searchUrl = "${mainUrl}arama/${query.replace(" ", "+")}" val doc = app.get(searchUrl).document return doc.select(".movie-box").mapNotNull { it.toSearchResult() } } private fun Element.toSearchResult(): SearchResponse? { val title = this.selectFirst(".title")?.text() ?: return null val href = fixUrlNull(this.selectFirst("a")?.attr("href")) ?: return null val posterUrl = this.selectFirst("img")?.attr("data-src") ?: this.selectFirst("img")?.attr("src") return newMovieSearchResponse(title, href, TvType.Movie) { this.posterUrl = fixUrl(posterUrl ?: "") } } override suspend fun load(url: String): LoadResponse { val doc = app.get(url).document val title = doc.selectFirst("h1")?.text()?.trim() ?: "" val poster = doc.selectFirst(".poster img")?.attr("src") val description = doc.selectFirst(".summary")?.text() val episodes = doc.select(".episode-list a").mapIndexed { index, element -> newEpisode(fixUrlNull(element.attr("href"))) { this.name = element.text() this.episode = index + 1 } } return newTvSeriesLoadResponse(title, url, TvType.TvSeries, episodes) { this.posterUrl = fixUrl(poster ?: "") this.plot = description } } override suspend fun loadLinks(data: String, isCasting: Boolean, subtitleCallback: (SubtitleFile) -> Unit, callback: (ExtractorLink) -> Unit): Boolean { val doc = app.get(data).document val iframeSrc = doc.selectFirst("iframe")?.attr("src") ?: return false loadExtractor(iframeSrc, data, subtitleCallback, callback) return true } }